24	import type { TaskDetail, PullRequestRef } from "@/services/workflow-backend/types";
25	
26	export type TaskTabViewProps = {
27	  workspaceId: string;
28	  taskId: string;
29	};
30	
31	export function TaskTabView({ workspaceId, taskId }: TaskTabViewProps) {
32	  const { task, loading, error, reload } = useWorkspaceTask(workspaceId, taskId);
33	
34	  if (loading) {
35	    return (
36	      <div
37	        data-task-tab-loading
38	        className="flex flex-1 items-center justify-center"
39	      >
40	        <p className="text-sm text-text-muted">Loading task…</p>
41	      </div>
42	    );
43	  }
44	
45	  if (error) {
46	    return (
47	      <div
48	        data-task-tab-error
49	        className="flex flex-1 flex-col items-center justify-center gap-4"
50	      >
51	        <AlertCircle className="h-8 w-8 text-danger" aria-hidden="true" />
52	        <p className="text-sm text-text-secondary">
53	          {error.message || "Failed to load task."}
54	        </p>
55	        {error.retryable && (
56	          <button
57	            type="button"
58	            onClick={reload}
