74	function TaskTabContent({
75	  task,
76	  onReload,
77	}: {
78	  task: TaskDetail;
79	  onReload: () => void;
80	}) {
81	  const { goToBoard } = useWorkspaceContext();
82	  const [copied, setCopied] = useState(false);
83	  const statusStyle = getStatusStyle(task.status);
84	
85	  function handleCopyId() {
86	    const textToCopy = task.task_name || task.id;
87	    if (navigator.clipboard) {
88	      navigator.clipboard.writeText(textToCopy).then(() => {
89	        setCopied(true);
90	        setTimeout(() => setCopied(false), 1500);
91	      });
92	    } else {
93	      const el = document.createElement("textarea");
94	      el.value = textToCopy;
95	      document.body.appendChild(el);
96	      el.select();
97	      document.execCommand("copy");
98	      document.body.removeChild(el);
99	      setCopied(true);
100	      setTimeout(() => setCopied(false), 1500);
101	    }
102	  }
103	
104	  return (
105	    <div
106	      data-task-tab-content
107	      className="flex h-full flex-col overflow-hidden"
108	    >
109	      {/* Task tab header */}
110	      <header className="flex shrink-0 items-center gap-3 border-b border-border bg-surface px-6 py-4">
111	        <button
112	          type="button"
113	          data-back-to-board
114	          onClick={goToBoard}
115	          aria-label="Back to board"
116	          className="flex items-center gap-1.5 text-xs text-text-secondary transition-colors hover:text-text-primary"
117	        >
118	          <ArrowLeft className="h-3.5 w-3.5" aria-hidden="true" />
119	          Board
120	        </button>
121	        <span className="h-4 w-px bg-border" aria-hidden="true" />
122	        <div className="flex min-w-0 flex-1 flex-wrap items-center gap-2">
123	          <button
124	            type="button"
125	            data-copy-task-id
126	            onClick={handleCopyId}
127	            aria-label={`Copy task id ${task.task_name}`}
128	            title="Copy task ID"
129	            className="flex items-center gap-1 bg-chip-bg px-2 py-0.5 text-xs font-semibold uppercase tracking-wide text-text-secondary transition-colors hover:bg-primary-light hover:text-primary"
130	          >
131	            {task.task_name}
132	            {copied ? (
133	              <Check className="h-3 w-3 text-success" aria-hidden="true" />
134	            ) : (
135	              <ClipboardCopy className="h-3 w-3" aria-hidden="true" />
136	            )}
137	          </button>
138	          <span
139	            className={
140	              "px-2 py-0.5 text-xs font-semibold uppercase tracking-wide " +
141	              statusStyle.bg +
142	              " " +
143	              statusStyle.text
144	            }
145	          >
146	            {formatStatusLabel(task.status)}
147	          </span>
148	          <h1 className="min-w-0 truncate text-base font-semibold text-text-primary">
149	            {task.title || task.task_name}
150	          </h1>
151	        </div>
152	        <button
153	          type="button"
154	          onClick={onReload}
155	          aria-label="Reload task"
156	          className="shrink-0 p-1 text-text-secondary transition-colors hover:text-text-primary"
157	        >
158	          <RefreshCw className="h-4 w-4" aria-hidden="true" />
159	        </button>
160	      </header>
161	
162	      {/* Task tab body — scrollable */}
163	      <div className="flex-1 overflow-y-auto px-6 py-6">
164	        <div className="mx-auto max-w-3xl space-y-8">
165	          <TaskMetadataSection task={task} />
166	          <TaskDependenciesSection task={task} />
167	          <TaskExecutionSection task={task} />
168	          <TaskPrRefsSection task={task} />
169	        </div>
170	      </div>
171	    </div>
172	  );
173	}
174	
175	function TaskMetadataSection({ task }: { task: TaskDetail }) {
176	  const repoUrl = task.repo ? `https://github.com/${task.repo}` : null;
177	
178	  return (
179	    <section>
180	      <h2 className="mb-4 text-xs font-semibold uppercase tracking-widest text-text-muted">
181	        Details
182	      </h2>
183	      <div className="grid grid-cols-2 gap-x-8 gap-y-5">
184	        <MetaField
185	          icon={<Layers className="h-4 w-4" aria-hidden="true" />}
186	          label="Repository"
187	        >
188	          {task.repo && repoUrl ? (
189	            <a
190	              href={repoUrl}
191	              target="_blank"
192	              rel="noreferrer noopener"
193	              className="inline-flex items-center gap-1.5 text-primary transition-colors hover:underline"
194	              aria-label={`Open repository ${task.repo}`}
195	            >
196	              <span className="text-text-primary">{task.repo}</span>
197	              <ExternalLink className="h-3.5 w-3.5" aria-hidden="true" />
198	            </a>
199	          ) : (
200	            <NoneValue />
201	          )}
202	        </MetaField>
203	
204	        <MetaField
205	          icon={<GitBranch className="h-4 w-4" aria-hidden="true" />}
206	          label="Branch"
207	        >
208	          {task.branch ? (
209	            <span className="break-all font-mono text-xs text-success">
210	              {task.branch}
211	            </span>
212	          ) : (
213	            <NoneValue />
214	          )}
215	        </MetaField>
216	
217	        {task.blocked_reason && (
218	          <MetaField
219	            icon={
220	              <AlertCircle
221	                className="h-4 w-4 text-danger"
222	                aria-hidden="true"
223	              />
224	            }
225	            label="Blocked Reason"
226	            fullWidth
227	          >
228	            <div
229	              data-blocked-reason
230	              className="flex items-start gap-2 border border-danger bg-danger-bg px-3 py-2"
231	            >
232	              <AlertCircle
233	                className="mt-0.5 h-4 w-4 shrink-0 text-danger"
234	                aria-hidden="true"
235	              />
236	              <span className="text-sm text-danger">{task.blocked_reason}</span>
237	            </div>
238	          </MetaField>
239	        )}
240	      </div>
241	    </section>
242	  );
243	}
244	
245	function TaskDependenciesSection({ task }: { task: TaskDetail }) {
246	  if (!task.depends_on || task.depends_on.length === 0) return null;
247	
248	  return (
249	    <section>
250	      <h2 className="mb-4 text-xs font-semibold uppercase tracking-widest text-text-muted">
251	        Dependencies
252	      </h2>
253	      <div
254	        data-task-depends-on
255	        className="flex flex-wrap gap-2"
256	      >
257	        {task.depends_on.map((dep) => (
258	          <span
259	            key={dep}
260	            className="bg-chip-bg px-2 py-0.5 font-mono text-xs font-medium text-text-secondary"
261	          >
262	            {dep}
263	          </span>
264	        ))}
265	      </div>
266	    </section>
267	  );
268	}
269	
270	function TaskExecutionSection({ task }: { task: TaskDetail }) {
271	  const { execution } = task;
272	  if (!execution) return null;
273	
274	  const actorType = execution.actor_type;
275	  const ActorIcon = actorType === "agent" ? Bot : User;
276	  const lastUpdatedAt = execution.last_updated_at;
277	  const lastUpdatedBy = execution.last_updated_by;
278	
279	  return (
280	    <section>
281	      <h2 className="mb-4 text-xs font-semibold uppercase tracking-widest text-text-muted">
282	        Execution
283	      </h2>
284	      <div
285	        data-task-execution
286	        className="grid grid-cols-2 gap-x-8 gap-y-5"
287	      >
288	        <MetaField
289	          icon={<ActorIcon className="h-4 w-4" aria-hidden="true" />}
290	          label="Actor"
291	        >
292	          <span className="capitalize text-text-primary">
293	            {actorType || <NoneValue />}
294	          </span>
295	        </MetaField>
296	
297	        {lastUpdatedBy && (
298	          <MetaField label="Last Updated By">
299	            <span className="text-text-primary">{lastUpdatedBy}</span>
300	          </MetaField>
301	        )}
302	
303	        {lastUpdatedAt && (
304	          <MetaField label="Last Updated">
305	            <span className="text-text-primary">
306	              {formatTimestamp(lastUpdatedAt)}
307	            </span>
308	          </MetaField>
309	        )}
310	      </div>
311	    </section>
312	  );
313	}
314	
315	function TaskPrRefsSection({ task }: { task: TaskDetail }) {
316	  const refs = task.pr_refs ?? [];
317	  const legacyPr = task.pr;
318	  const legacyWsPr = task.workspace_pr;
319	
320	  const allRefs: PullRequestRef[] = [...refs];
321	
322	  if (legacyPr?.url && !allRefs.some((r) => r.url === legacyPr.url)) {
323	    allRefs.push({
324	      label: "Repository PR",
325	      status: legacyPr.status ?? "",
326	      repo: task.repo ?? "",
327	      url: legacyPr.url,
328	    });
329	  }
330	  if (legacyWsPr?.url && !allRefs.some((r) => r.url === legacyWsPr.url)) {
331	    allRefs.push({
332	      label: "Workspace PR",
333	      status: legacyWsPr.status ?? "",
334	      repo: "",
335	      url: legacyWsPr.url,
336	    });
337	  }
338	
339	  if (allRefs.length === 0) return null;
340	
341	  return (
342	    <section>
343	      <h2 className="mb-4 text-xs font-semibold uppercase tracking-widest text-text-muted">
344	        Pull Requests
345	      </h2>
346	      <div
347	        data-task-pr-refs
348	        className="flex flex-col gap-2"
349	      >
350	        {allRefs.map((ref) => (
351	          <PrRefCard key={ref.url} ref_={ref} />
352	        ))}
353	      </div>
354	    </section>
355	  );
356	}
357	
358	function PrRefCard({ ref_ }: { ref_: PullRequestRef }) {
359	  return (
360	    <a
361	      href={ref_.url}
362	      target="_blank"
363	      rel="noreferrer noopener"
364	      data-pr-ref={ref_.url}
365	      className="flex items-center justify-between border border-border bg-surface px-3 py-2.5 transition-colors hover:border-primary-light hover:bg-surface-subtle"
366	    >
367	      <div className="flex items-center gap-2">
368	        <GitPullRequest
369	          className="h-4 w-4 text-text-secondary"
370	          aria-hidden="true"
371	        />
372	        <span className="text-sm font-medium text-text-primary">
373	          {ref_.label || ref_.repo || "PR"}
374	        </span>
375	        {ref_.status && (
376	          <span className="rounded bg-chip-bg px-1.5 text-[10px] font-medium uppercase text-text-secondary">
377	            {ref_.status}
378	          </span>
379	        )}
380	      </div>
381	      <ExternalLink
382	        className="h-3.5 w-3.5 text-text-muted"
383	        aria-hidden="true"
384	      />
385	    </a>
386	  );
387	}
388	
389	function MetaField({
390	  icon,
391	  label,
392	  fullWidth,
393	  children,
394	}: {
395	  icon?: React.ReactNode;
396	  label: string;
397	  fullWidth?: boolean;
398	  children: React.ReactNode;
399	}) {
400	  return (
401	    <div
402	      className={"flex flex-col gap-1.5 " + (fullWidth ? "col-span-2" : "")}
403	    >
404	      <div className="flex items-center gap-1.5 text-xs font-medium uppercase tracking-wide text-text-secondary">
405	        {icon}
406	        <span>{label}</span>
407	      </div>
408	      <div className="text-sm">{children}</div>
409	    </div>
410	  );
411	}
412	
413	function NoneValue() {
414	  return <span className="italic text-text-muted">None</span>;
415	}
