1	/**
2	 * Regression tests for TaskBoardView prop pass-throughs.
3	 *
4	 * Verifies that TaskBoardView correctly wires:
5	 *   - toggleFeature (feature expansion) — expandedFeatureIds drives aria-expanded on FeatureRow
6	 *   - setSelectedTask (task detail selection) — task cards are rendered for expanded rows
7	 *     and the callback is not spuriously called during rendering
8	 */
9	import React from "react";
10	import { renderToStaticMarkup } from "react-dom/server";
11	import { beforeEach, describe, expect, it, vi } from "vitest";
12	import type { ParsedFeature } from "../services/yaml-parser";
13	import type { ActiveFilters, FeatureActiveFilters } from "../features/board/types";
14	
15	// ─── Board context mock ────────────────────────────────────────────────────────
16	
17	const mockToggleFeature = vi.hoisted(() => vi.fn());
18	const mockSetSelectedTask = vi.hoisted(() => vi.fn());
19	
20	// Mutable ref so individual tests can override context values.
21	const mockContextRef = vi.hoisted(() => ({
22	  current: null as unknown,
23	}));
24	
25	vi.mock("../features/board/components/KanbanBoard/KanbanBoard.context", () => ({
26	  useBoardContext: () => mockContextRef.current,
27	}));
28	
29	import { TaskBoardView } from "../features/board/components/TaskBoardView/TaskBoardView";
30	
31	// ─── Context factory ──────────────────────────────────────────────────────────
32	
33	function buildContext(opts: {
34	  features?: ParsedFeature[];
35	  expandedFeatureIds?: Set<string>;
36	  taskSearchQuery?: string;
37	  taskActiveFilters?: ActiveFilters;
38	}) {
39	  const taskFilters: ActiveFilters = opts.taskActiveFilters ?? { statuses: [] };
40	  const featureFilters: FeatureActiveFilters = { statuses: [] };
41	
42	  return {
43	    workspace: {
44	      id: "test-ws",
45	      owner: "test-owner",
46	      repo: "test-repo",
47	      name: "Test Workspace",
48	      isPrivate: false,
49	      connectedAt: "2026-01-01T00:00:00Z",
50	    },
51	    features: opts.features ?? [],
52	    trackedFeatures: [],
53	    loading: false,
54	    error: null,
55	    reload: vi.fn(),
56	    boardMode: "task" as const,
57	    setBoardMode: vi.fn(),
58	    taskSearchQuery: opts.taskSearchQuery ?? "",
59	    setTaskSearchQuery: vi.fn(),
60	    taskActiveFilters: taskFilters,
61	    setTaskActiveFilters: vi.fn(),
62	    featureSearchQuery: "",
63	    setFeatureSearchQuery: vi.fn(),
64	    featureActiveFilters: featureFilters,
65	    setFeatureActiveFilters: vi.fn(),
66	    // Legacy aliases
67	    searchQuery: opts.taskSearchQuery ?? "",
68	    setSearchQuery: vi.fn(),
69	    activeFilters: taskFilters,
70	    setActiveFilters: vi.fn(),
71	    expandedFeatureIds: opts.expandedFeatureIds ?? new Set<string>(),
72	    toggleFeature: mockToggleFeature,
73	    selectedTask: null,
74	    setSelectedTask: mockSetSelectedTask,
75	    selectedFeature: null,
76	    setSelectedFeature: vi.fn(),
77	    syncing: false,
78	    syncError: null,
79	    syncBoard: vi.fn(),
80	    backendTaskResults: null as import("../services/yaml-parser").ParsedFeature[] | null,
81	    backendFeatureResults: null as import("../services/yaml-parser").ParsedFeature[] | null,
82	    taskSearching: false,
83	    featureSearching: false,
84	    taskSearchError: null,
85	    featureSearchError: null,
86	    workspaceDetail: {
87	      id: "test-ws",
88	      name: "Test Workspace",
89	      slug: "test-ws",
90	      repo_url: "https://github.com/test/repo",
91	      source_state: { stale: false },
92	      updated_at: "2026-01-01T00:00:00Z",
93	      features: [],
94	      tasks: [],
95	    },
96	    openTaskTab: vi.fn(),
97	  };
98	}
99	
100	// ─── Test helpers ─────────────────────────────────────────────────────────────
101	
102	function makeFeature(overrides: Partial<ParsedFeature> = {}): ParsedFeature {
103	  return {
104	    id: "alpha-feature",
105	    title: "Alpha Feature",
106	    featureStatus: "in_implementation",
107	    tasks: [],
108	    ...overrides,
109	  };
110	}
111	
112	function makeTask(id: string, title: string, status: string) {
113	  return { id, title, status, dependsOn: [] };
114	}
115	
116	beforeEach(() => {
117	  mockToggleFeature.mockClear();
118	  mockSetSelectedTask.mockClear();
119	});
120	
121	// ─── Feature expansion wiring ─────────────────────────────────────────────────
122	
123	describe("TaskBoardView — feature expansion wiring (toggleFeature)", () => {
124	  it("renders FeatureRow with aria-expanded=false when feature is not in expandedFeatureIds", () => {
125	    mockContextRef.current = buildContext({
126	      features: [makeFeature()],
127	      expandedFeatureIds: new Set<string>(),
128	    });
129	
130	    const html = renderToStaticMarkup(React.createElement(TaskBoardView));
131	    expect(html).toContain('aria-expanded="false"');
132	  });
133	
134	  it("renders FeatureRow with aria-expanded=true when feature id is in expandedFeatureIds", () => {
135	    mockContextRef.current = buildContext({
136	      features: [makeFeature()],
137	      expandedFeatureIds: new Set<string>(["alpha-feature"]),
138	    });
139	
140	    const html = renderToStaticMarkup(React.createElement(TaskBoardView));
141	    expect(html).toContain('aria-expanded="true"');
142	  });
143	
144	  it("each feature gets independent expansion state from expandedFeatureIds", () => {
145	    mockContextRef.current = buildContext({
146	      features: [
147	        makeFeature({ id: "feat-a", title: "Feature A" }),
148	        makeFeature({ id: "feat-b", title: "Feature B" }),
149	      ],
150	      expandedFeatureIds: new Set<string>(["feat-a"]), // only feat-a is expanded
151	    });
152	
153	    const html = renderToStaticMarkup(React.createElement(TaskBoardView));
154	    // One row expanded, one collapsed
155	    expect(html).toContain('aria-expanded="true"');
156	    expect(html).toContain('aria-expanded="false"');
157	  });
158	
159	  it("toggleFeature from context is not called during rendering", () => {
160	    mockContextRef.current = buildContext({ features: [makeFeature()] });
161	
162	    renderToStaticMarkup(React.createElement(TaskBoardView));
163	    expect(mockToggleFeature).not.toHaveBeenCalled();
164	  });
165	});
166	
167	// ─── Task detail selection wiring ─────────────────────────────────────────────
168	
169	describe("TaskBoardView — task detail selection wiring (setSelectedTask)", () => {
170	  it("renders task cards inside an expanded feature row, confirming onSelectTask is wired", () => {
171	    const feature = makeFeature({
172	      tasks: [makeTask("T1", "Setup OAuth providers", "todo")],
